/* Blog navigation uses the headings and fragment IDs generated by Jekyll. */
(function () {
  "use strict";

  var HEADER_OFFSET = 86;
  var desktop = window.matchMedia("(min-width: 1280px)");
  var initialized = false;
  var root;
  var headings = [];
  var links = [];
  var tocMenu;
  var current = -1;
  var framePending = false;
  var revealPending = false;
  var allowHashCorrection = true;
  var menus = [];

  function menuState(menu) {
    for (var i = 0; i < menus.length; i += 1) {
      if (menus[i].element === menu) return menus[i];
    }
    return null;
  }

  function watchMenu(menu) {
    var state = { element: menu, hovered: false, busyUntil: 0 };
    menus.push(state);
    menu.addEventListener("mouseenter", function () { state.hovered = true; });
    menu.addEventListener("mouseleave", function () { state.hovered = false; });
    function interacting() { state.busyUntil = Date.now() + 1500; }
    menu.addEventListener("wheel", interacting, { passive: true });
    menu.addEventListener("touchstart", interacting, { passive: true });
    menu.addEventListener("pointerdown", interacting, { passive: true });
  }

  // Scroll only the menu. scrollIntoView() can also move the article itself.
  function revealLink(link, menu) {
    if (!link || !menu || !menu.clientHeight || !link.getClientRects().length) return;
    var state = menuState(menu);
    if (menu.contains(document.activeElement) ||
        (state && (state.hovered || state.busyUntil > Date.now()))) return;

    var viewport = menu.getBoundingClientRect();
    var item = link.getBoundingClientRect();
    var padding = 8;
    if (item.top < viewport.top + padding) {
      menu.scrollTop += item.top - viewport.top - padding;
    } else if (item.bottom > viewport.bottom - padding) {
      menu.scrollTop += item.bottom - viewport.bottom + padding;
    }
  }

  function updateActive() {
    framePending = false;
    if (!headings.length) return;
    var next = 0;
    for (var i = 0; i < headings.length; i += 1) {
      if (headings[i].getBoundingClientRect().top <= HEADER_OFFSET + 1) next = i;
      else break;
    }

    if (next !== current) {
      if (current >= 0) {
        links[current].classList.remove("is-active");
        links[current].removeAttribute("aria-current");
      }
      current = next;
      links[current].classList.add("is-active");
      links[current].setAttribute("aria-current", "location");
      revealPending = true;
    }
    if (revealPending) revealLink(links[current], tocMenu);
    revealPending = false;
  }

  function scheduleActive(reveal) {
    if (reveal === true) revealPending = true;
    if (framePending) return;
    framePending = true;
    window.requestAnimationFrame(updateActive);
  }

  function hashTarget() {
    if (!window.location.hash || window.location.hash === "#") return null;
    var id;
    try { id = decodeURIComponent(window.location.hash.slice(1)); }
    catch (error) { return null; }
    var target = document.getElementById(id);
    return target && root.contains(target) ? target : null;
  }

  function correctHashPosition() {
    if (!allowHashCorrection) return;
    var target = hashTarget();
    if (!target || !target.getClientRects().length) return;
    var difference = target.getBoundingClientRect().top - HEADER_OFFSET;
    // Keep native fragment history; only compensate for layout changes.
    if (Math.abs(difference) > 1) window.scrollBy(0, difference);
    scheduleActive(true);
  }

  function refreshLayout() {
    if (!initialized) return;
    // Give MathJax, details, and native fragment scrolling a layout frame.
    window.requestAnimationFrame(function () {
      window.requestAnimationFrame(function () {
        correctHashPosition();
        scheduleActive(true);
      });
    });
  }

  function createTOC(container) {
    var article = root.querySelector(".page__content");
    var candidates = article ? article.querySelectorAll("h1[id], h2[id], h3[id], h4[id], h5[id], h6[id]") :
      root.querySelectorAll(".archive__subtitle[id]");
    var list = document.createElement("ul");
    list.className = "blog-navigation__list";
    var parents = [];

    for (var i = 0; i < candidates.length; i += 1) {
      var heading = candidates[i];
      if (!heading.id || heading.closest(".no_toc, pre, code, nav")) continue;
      var label = heading.textContent.trim();
      if (!label) continue;
      var level = parseInt(heading.tagName.slice(1), 10) || 2;
      while (parents.length && parents[parents.length - 1].level >= level) parents.pop();

      var parentList = list;
      if (parents.length) {
        var parentItem = parents[parents.length - 1].item;
        parentList = parentItem.lastElementChild;
        if (!parentList || parentList.tagName !== "UL") {
          parentList = document.createElement("ul");
          parentList.className = "blog-navigation__list";
          parentItem.appendChild(parentList);
        }
      }

      var item = document.createElement("li");
      var link = document.createElement("a");
      link.setAttribute("href", "#" + encodeURIComponent(heading.id));
      link.textContent = label;
      item.appendChild(link);
      parentList.appendChild(item);
      parents.push({ level: level, item: item });
      headings.push(heading);
      links.push(link);
    }

    if (headings.length) container.appendChild(list);
    var sidebar = container.closest(".blog-navigation--toc");
    if (sidebar) sidebar.hidden = !headings.length;
  }

  function syncDetails() {
    var details = root.querySelectorAll(".blog-navigation__details");
    for (var i = 0; i < details.length; i += 1) {
      details[i].open = desktop.matches;
      var summary = details[i].querySelector("summary");
      if (summary) {
        if (desktop.matches) summary.setAttribute("tabindex", "-1");
        else summary.removeAttribute("tabindex");
      }
    }
    window.requestAnimationFrame(function () {
      if (desktop.matches) {
        var selectedPost = root.querySelector('.blog-navigation--posts [aria-current="page"]');
        if (selectedPost) revealLink(selectedPost, selectedPost.closest(".blog-navigation__scroll"));
      }
      scheduleActive(true);
    });
  }

  function initialize() {
    if (initialized) return;
    root = document.querySelector("#main.blog-layout");
    if (!root) return;
    initialized = true;
    tocMenu = root.querySelector("#blog-toc");
    if (tocMenu) createTOC(tocMenu);

    var scrollMenus = root.querySelectorAll(".blog-navigation__scroll");
    for (var i = 0; i < scrollMenus.length; i += 1) watchMenu(scrollMenus[i]);

    var details = root.querySelectorAll(".blog-navigation__details");
    for (var j = 0; j < details.length; j += 1) {
      var summary = details[j].querySelector("summary");
      if (summary) summary.addEventListener("click", function (event) {
        if (desktop.matches) event.preventDefault();
      });
      details[j].addEventListener("toggle", function () {
        if (desktop.matches && !this.open) this.open = true;
        if (this.open) scheduleActive(true);
      });
    }

    syncDetails();
    if (desktop.addEventListener) desktop.addEventListener("change", syncDetails);
    else desktop.addListener(syncDetails);

    window.addEventListener("scroll", function () { scheduleActive(false); }, { passive: true });
    window.addEventListener("resize", function () { scheduleActive(true); }, { passive: true });
    window.addEventListener("hashchange", function () {
      allowHashCorrection = true;
      refreshLayout();
    });
    window.addEventListener("load", refreshLayout);

    // A slow MathJax download must not pull a reader back after they scroll.
    function pageInteraction(event) {
      if (event.target instanceof Element && event.target.closest(".blog-navigation")) return;
      allowHashCorrection = false;
    }
    window.addEventListener("wheel", pageInteraction, { passive: true });
    window.addEventListener("touchstart", pageInteraction, { passive: true });
    window.addEventListener("pointerdown", pageInteraction, { passive: true });
    window.addEventListener("keydown", function (event) {
      if (["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End", " "].indexOf(event.key) !== -1) {
        pageInteraction(event);
      }
    });
    refreshLayout();
  }

  // This file is loaded before MathJax. Build labels from original TeX before
  // its first typesetting pass, and keep any previously configured callback.
  var mathjax = window.MathJax = window.MathJax || {};
  var startup = mathjax.startup = mathjax.startup || {};
  var previousPageReady = startup.pageReady;
  startup.pageReady = function () {
    initialize();
    var ready = previousPageReady ? previousPageReady.apply(this, arguments) :
      window.MathJax.startup.defaultPageReady();
    return Promise.resolve(ready).then(function (result) {
      refreshLayout();
      return result;
    });
  };

  // Navigation remains usable if the external MathJax loader fails.
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initialize);
  else initialize();
}());
